import { Router, type Request, type Response } from 'express';

export interface BookmarkInput {
  url: string;
  title?: string;
  tags?: string[];
}

export function isBookmarkInput(value: unknown): value is BookmarkInput {
  if (typeof value !== 'object' || value === null) {
    return false;
  }

  const record = value as Record<string, unknown>;

  if (typeof record.url !== 'string') {
    return false;
  }

  if (record.title !== undefined && typeof record.title !== 'string') {
    return false;
  }

  if (record.tags !== undefined) {
    if (!Array.isArray(record.tags)) {
      return false;
    }
    for (const tag of record.tags) {
      if (typeof tag !== 'string') {
        return false;
      }
    }
  }

  return true;
}

export const bookmarksRouter = Router();

bookmarksRouter.post(['/', '/api/v1/bookmarks'], (req: Request, res: Response): void => {
  const body: unknown = req.body;

  if (!isBookmarkInput(body)) {
    res.status(400).json({ error: 'Invalid bookmark payload' });
    return;
  }

  res.status(201).json({
    url: body.url,
    ...(body.title !== undefined ? { title: body.title } : {}),
    ...(body.tags !== undefined ? { tags: body.tags } : {}),
  });
});

export default bookmarksRouter;

