import { randomUUID } from 'node:crypto';

export interface Bookmark {
  id: string;
  url: string;
  title?: string;
  tags?: string[];
  createdAt: string;
}

export interface CreateBookmarkDTO {
  url: string;
  title?: string;
  tags?: string[];
}

export class DuplicateBookmarkError extends Error {
  constructor(url: string) {
    super(`Bookmark with URL "${url}" already exists`);
    this.name = 'DuplicateBookmarkError';
  }
}

export function isBookmark(value: unknown): value is Bookmark {
  if (typeof value !== 'object' || value === null) {
    return false;
  }
  const record = value as Record<string, unknown>;
  return (
    typeof record.id === 'string' &&
    typeof record.url === 'string' &&
    typeof record.createdAt === 'string' &&
    (record.title === undefined || typeof record.title === 'string') &&
    (record.tags === undefined ||
      (Array.isArray(record.tags) && record.tags.every((t: unknown): t is string => typeof t === 'string')))
  );
}

export function isCreateBookmarkDTO(value: unknown): value is CreateBookmarkDTO {
  if (typeof value !== 'object' || value === null) {
    return false;
  }
  const record = value as Record<string, unknown>;
  return (
    typeof record.url === 'string' &&
    (record.title === undefined || typeof record.title === 'string') &&
    (record.tags === undefined ||
      (Array.isArray(record.tags) && record.tags.every((t: unknown): t is string => typeof t === 'string')))
  );
}

export class BookmarkService {
  private readonly bookmarks = new Map<string, Bookmark>();

  public create(dto: CreateBookmarkDTO): Bookmark {
    for (const bookmark of this.bookmarks.values()) {
      if (bookmark.url === dto.url) {
        throw new DuplicateBookmarkError(dto.url);
      }
    }

    const id = randomUUID();
    const bookmark: Bookmark = {
      id,
      url: dto.url,
      ...(dto.title !== undefined ? { title: dto.title } : {}),
      ...(dto.tags !== undefined ? { tags: dto.tags } : {}),
      createdAt: new Date().toISOString(),
    };

    this.bookmarks.set(id, bookmark);
    return bookmark;
  }

  public getById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  public getAll(): Bookmark[] {
    return Array.from(this.bookmarks.values());
  }

  public delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  public clear(): void {
    this.bookmarks.clear();
  }
}

import { Router, type Request, type Response } from 'express';
import { z } from 'zod';
import { BookmarkService, DuplicateBookmarkError } from '../services/bookmark-service.js';

export const createBookmarkSchema = z.object({
  url: z.string().url('Must be a valid URL').max(2048, 'URL must not exceed 2048 characters'),
  title: z.string().max(200, 'Title must not exceed 200 characters').optional(),
  tags: z
    .array(z.string().max(50, 'Tag must not exceed 50 characters'))
    .max(10, 'Tags array must not exceed 10 items')
    .optional(),
});

export type CreateBookmarkInput = z.infer<typeof createBookmarkSchema>;

export function isBookmarkInput(value: unknown): value is CreateBookmarkInput {
  return createBookmarkSchema.safeParse(value).success;
}

export const bookmarkService = new BookmarkService();
export const bookmarksRouter = Router();

bookmarksRouter.post(['/', '/api/v1/bookmarks'], (req: Request, res: Response): void => {
  const body: unknown = req.body;
  const result = createBookmarkSchema.safeParse(body);

  if (!result.success) {
    res.status(400).json({
      error: 'Validation failed',
      details: result.error.issues,
    });
    return;
  }

  try {
    const bookmark = bookmarkService.create(result.data);
    res.status(201).json(bookmark);
  } catch (error: unknown) {
    if (error instanceof DuplicateBookmarkError) {
      res.status(409).json({ error: error.message });
      return;
    }
    throw error;
  }
});

export default bookmarksRouter;

