import { describe, it, expect } from 'vitest';
import { createBookmarkSchema } from './bookmarks.js';

describe('createBookmarkSchema', () => {
  it('should validate valid inputs with minimal fields', () => {
    const input: unknown = {
      url: 'https://example.com',
    };

    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data.url).toBe('https://example.com');
      expect(result.data.title).toBeUndefined();
      expect(result.data.tags).toBeUndefined();
    }
  });

  it('should validate valid inputs with all optional fields provided', () => {
    const input: unknown = {
      url: 'https://example.com/articles/typescript',
      title: 'Learning TypeScript in 2026',
      tags: ['typescript', 'node', 'express'],
    };

    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data.url).toBe('https://example.com/articles/typescript');
      expect(result.data.title).toBe('Learning TypeScript in 2026');
      expect(result.data.tags).toEqual(['typescript', 'node', 'express']);
    }
  });

  it('should fail validation when url is missing', () => {
    const input: unknown = {
      title: 'Bookmark without URL',
      tags: ['test'],
    };

    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const urlIssue = result.error.issues.find((issue) => issue.path.includes('url'));
      expect(urlIssue).toBeDefined();
    }
  });

  it('should fail validation when url is too long (> 2048 chars)', () => {
    const longUrl = 'https://example.com/' + 'a'.repeat(2050);
    const input: unknown = {
      url: longUrl,
    };

    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const urlIssue = result.error.issues.find((issue) => issue.path.includes('url'));
      expect(urlIssue).toBeDefined();
      expect(urlIssue?.message).toContain('2048');
    }
  });

  it('should fail validation when there are too many tags (> 10)', () => {
