import { describe, it, expect, beforeEach } from 'vitest';
import { BookmarkService, DuplicateBookmarkError } from './bookmark-service.js';

describe('BookmarkService', () => {
  let service: BookmarkService;

  beforeEach(() => {
    service = new BookmarkService();
  });

  describe('create', () => {
    it('should create and store a bookmark with generated id and createdAt', () => {
      const bookmark = service.create({
        url: 'https://example.com/vitest',
        title: 'Vitest Documentation',
        tags: ['testing', 'vitest'],
      });

      expect(bookmark.id).toBeDefined();
      expect(typeof bookmark.id).toBe('string');
      expect(bookmark.id.length).toBeGreaterThan(0);
      expect(bookmark.url).toBe('https://example.com/vitest');
      expect(bookmark.title).toBe('Vitest Documentation');
      expect(bookmark.tags).toEqual(['testing', 'vitest']);
      expect(bookmark.createdAt).toBeDefined();
      expect(new Date(bookmark.createdAt).toISOString()).toBe(bookmark.createdAt);
    });

    it('should create a bookmark without optional title and tags', () => {
      const bookmark = service.create({
        url: 'https://example.com/minimal',
      });

      expect(bookmark.id).toBeDefined();
      expect(bookmark.url).toBe('https://example.com/minimal');
      expect(bookmark.title).toBeUndefined();
      expect(bookmark.tags).toBeUndefined();
    });
  });

  describe('duplicate detection', () => {
    it('should throw DuplicateBookmarkError when creating a bookmark with an already existing URL', () => {
      service.create({
        url: 'https://example.com/unique',
        title: 'First Entry',
      });

      expect(() => {
        service.create({
          url: 'https://example.com/unique',
          title: 'Duplicate Entry',
        });
      }).toThrow(DuplicateBookmarkError);
    });

    it('should include the duplicated URL in the error message', () => {
      const duplicateUrl = 'https://example.com/another-dup';
      service.create({ url: duplicateUrl });

      expect(() => {
        service.create({ url: duplicateUrl });
      }).toThrow(`Bookmark with URL "${duplicateUrl}" already exists`);
    });
  });

  describe('retrieval', () => {
    it('should retrieve an existing bookmark by id via getById', () => {
      const created = service.create({
        url: 'https://example.com/retrieval-test',
        title: 'Retrieve Me',
        tags: ['retrieval'],
      });

      const retrieved = service.getById(created.id);
      expect(retrieved).toBeDefined();
      expect(retrieved).toEqual(created);
    });

    it('should return undefined when retrieving a non-existent id via getById', () => {
      const result = service.getById('non-existent-uuid');
      expect(result).toBeUndefined();
    });

    it('should retrieve all stored bookmarks via getAll', () => {
      expect(service.getAll()).toEqual([]);

      const b1 = service.create({ url: 'https://example.com/1' });
      const b2 = service.create({ url: 'https://example.com/2' });

      const all = service.getAll();
      expect(all).toHaveLength(2);
      expect(all).toContainEqual(b1);
      expect(all).toContainEqual(b2);
    });
  });
});

