import { describe, it, expect, beforeEach } from 'vitest';
import request from 'supertest';
import { app } from '../src/app.js';
import { bookmarkService } from '../src/routes/bookmarks.js';
import { isBookmark } from '../src/services/bookmark-service.js';

describe('Bookmarks API Integration Tests', () => {
  beforeEach(() => {
    bookmarkService.clear();
  });

  describe('POST /api/v1/bookmarks', () => {
    it('should create a new bookmark and return 201 with generated id and createdAt', async () => {
      const payload = {
        url: 'https://example.com/integration',
        title: 'Integration Test Bookmark',
        tags: ['integration', 'test'],
      };

      const response = await request(app)
        .post('/api/v1/bookmarks')
        .send(payload)
        .expect(201);

      const body: unknown = response.body;
      expect(isBookmark(body)).toBe(true);

      if (isBookmark(body)) {
        expect(body.url).toBe(payload.url);
        expect(body.title).toBe(payload.title);
        expect(body.tags).toEqual(payload.tags);
        expect(body.id).toBeDefined();
        expect(body.createdAt).toBeDefined();
      }
    });
  });

  describe('GET /api/v1/bookmarks', () => {
    it('should return a list of all bookmarks sorted by createdAt descending', async () => {
      const res1 = await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://example.com/first', title: 'First' })
        .expect(201);

      await new Promise((resolve) => setTimeout(resolve, 5));

      const res2 = await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://example.com/second', title: 'Second' })
        .expect(201);

      const response = await request(app)
        .get('/api/v1/bookmarks')
        .expect(200);

      const body: unknown = response.body;
      expect(Array.isArray(body)).toBe(true);

      if (Array.isArray(body)) {
        expect(body.length).toBe(2);
        const [first, second] = body as unknown[];
        expect(isBookmark(first)).toBe(true);
        expect(isBookmark(second)).toBe(true);

        if (isBookmark(first) && isBookmark(second)) {
          const body1: unknown = res1.body;
          const body2: unknown = res2.body;
          if (isBookmark(body1) && isBookmark(body2)) {
            expect(first.id).toBe(body2.id);
            expect(second.id).toBe(body1.id);
          }
        }
      }
    });
  });

  describe('GET /api/v1/bookmarks/:id', () => {
    it('should return a single bookmark by id with 200 status', async () => {
      const createdRes = await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://example.com/single', title: 'Single' })
        .expect(201);

      const created: unknown = createdRes.body;
      expect(isBookmark(created)).toBe(true);

      if (isBookmark(created)) {
        const response = await request(app)
          .get(`/api/v1/bookmarks/${created.id}`)
          .expect(200);

        const body: unknown = response.body;
        expect(isBookmark(body)).toBe(true);
        if (isBookmark(body)) {
          expect(body.id).toBe(created.id);
          expect(body.url).toBe(created.url);
          expect(body.title).toBe(created.title);
        }
      }
    });
  });

  describe('DELETE /api/v1/bookmarks/:id', () => {
    it('should delete a bookmark and return 204, then return 404 on subsequent get', async () => {
      const createdRes = await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://example.com/to-delete', title: 'To Delete' })
        .expect(201);

      const created: unknown = createdRes.body;
      expect(isBookmark(created)).toBe(true);

      if (isBookmark(created)) {
        await request(app)
          .delete(`/api/v1/bookmarks/${created.id}`)
          .expect(204);

        await request(app)
          .get(`/api/v1/bookmarks/${created.id}`)
          .expect(404);
      }
    });
  });
});

