export function parsePaginationParams(query: unknown): PaginationParams {
  const record = typeof query === 'object' && query !== null ? (query as Record<string, unknown>) : {};

  let page = 1;
  if (typeof record.page === 'string') {
    const parsed = parseInt(record.page, 10);
    if (!isNaN(parsed)) {
      page = parsed;
    }
  } else if (typeof record.page === 'number' && !isNaN(record.page)) {
    page = Math.trunc(record.page);
  }

  let limit = 20;
  if (typeof record.limit === 'string') {
    const parsed = parseInt(record.limit, 10);
    if (!isNaN(parsed)) {
      limit = parsed;
    }
  } else if (typeof record.limit === 'number' && !isNaN(record.limit)) {
    limit = Math.trunc(record.limit);
  }

  if (page < 1) {
    page = 1;
  }
  if (limit < 1) {
    limit = 1;
  }
  if (limit > 100) {
    limit = 100;
  }

  return { page, limit };
}

