describe('parsePaginationParams edge cases', () => {
  it('should clamp page 0 to page 1', () => {
    const query: unknown = { page: '0', limit: '20' };
    const params = parsePaginationParams(query);
    expect(params.page).toBe(1);
    expect(params.limit).toBe(20);
  });

  it('should clamp negative page to page 1', () => {
    const query: unknown = { page: '-3' };
    const params = parsePaginationParams(query);
    expect(params.page).toBe(1);
  });

  it('should clamp negative limit to 1', () => {
