  describe('PATCH /api/v1/bookmarks/:id', () => {
    it('should partially update title and leave tags/url untouched', async () => {
      const createdRes = await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://example.com/patch-title', title: 'Initial Title', tags: ['keep-me'] })
        .expect(201);

      const created: unknown = createdRes.body;
      expect(isBookmark(created)).toBe(true);

      if (isBookmark(created)) {
        const patchRes = await request(app)
          .patch(`/api/v1/bookmarks/${created.id}`)
          .send({ title: 'Modified Title' })
          .expect(200);

        const updated: unknown = patchRes.body;
        expect(isBookmark(updated)).toBe(true);
        if (isBookmark(updated)) {
          expect(updated.id).toBe(created.id);
          expect(updated.title).toBe('Modified Title');
          expect(updated.tags).toEqual(['keep-me']);
          expect(updated.url).toBe('https://example.com/patch-title');
        }
      }
    });

    it('should partially update tags and leave title/url untouched', async () => {
      const createdRes = await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://example.com/patch-tags', title: 'Steady Title', tags: ['old-tag'] })
        .expect(201);

      const created: unknown = createdRes.body;
      expect(isBookmark(created)).toBe(true);

      if (isBookmark(created)) {
        const patchRes = await request(app)
          .patch(`/api/v1/bookmarks/${created.id}`)
          .send({ tags: ['updated-1', 'updated-2'] })
          .expect(200);

        const updated: unknown = patchRes.body;
        expect(isBookmark(updated)).toBe(true);
        if (isBookmark(updated)) {
          expect(updated.id).toBe(created.id);
          expect(updated.title).toBe('Steady Title');
          expect(updated.tags).toEqual(['updated-1', 'updated-2']);
          expect(updated.url).toBe('https://example.com/patch-tags');
        }
      }
    });

    it('should return 404 when attempting to patch a non-existent ID', async () => {
      const response = await request(app)
        .patch('/api/v1/bookmarks/non-existent-uuid')
        .send({ title: 'Ghost Bookmark' })
        .expect(404);

      const body: unknown = response.body;
      if (typeof body === 'object' && body !== null) {
        const record = body as Record<string, unknown>;
        expect(record.error).toBe('Bookmark not found');
      }
    });

    it('should reject URL change attempt with 400 Bad Request', async () => {
      const createdRes = await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://example.com/original-immutable', title: 'Immutable' })
        .expect(201);

      const created: unknown = createdRes.body;
      expect(isBookmark(created)).toBe(true);

      if (isBookmark(created)) {
        const patchRes = await request(app)
          .patch(`/api/v1/bookmarks/${created.id}`)
          .send({ url: 'https://example.com/attempted-url-mutation' })
          .expect(400);

        const body: unknown = patchRes.body;
        if (typeof body === 'object' && body !== null) {
          const record = body as Record<string, unknown>;
          expect(record.error).toBe('URL is immutable and cannot be updated');
        }

        // Verify the original URL was preserved in store
        const getRes = await request(app)
          .get(`/api/v1/bookmarks/${created.id}`)
          .expect(200);

        const fetched: unknown = getRes.body;
        if (isBookmark(fetched)) {
          expect(fetched.url).toBe('https://example.com/original-immutable');
        }
      }
    });
  });
});

