import { describe, it, expect, vi } from 'vitest';
import { EventEmitter } from 'node:events';
import type { Request, Response, NextFunction } from 'express';
import { requestLogger, isRequestLogEntry, type RequestLogEntry } from './request-logger.js';

describe('requestLogger middleware', () => {
  it('should log request details as JSON on finish', async () => {
    const consoleSpy = vi.spyOn(console, 'log').mockImplementation(() => {});

    const req = {
      method: 'GET',
      path: '/api/v1/bookmarks',
    } as Request;

    const resEmitter = new EventEmitter();
    const res = Object.assign(resEmitter, {
      statusCode: 200,
    }) as unknown as Response;

    const next = vi.fn() as NextFunction;

    requestLogger(req, res, next);
    expect(next).toHaveBeenCalledTimes(1);

    // Simulate small duration
    await new Promise((resolve) => setTimeout(resolve, 5));
    resEmitter.emit('finish');

    expect(consoleSpy).toHaveBeenCalledTimes(1);

    const loggedRaw: unknown = consoleSpy.mock.calls[0]?.[0];
    expect(typeof loggedRaw).toBe('string');

    if (typeof loggedRaw === 'string') {
      const parsed: unknown = JSON.parse(loggedRaw);
      expect(isRequestLogEntry(parsed)).toBe(true);

      if (isRequestLogEntry(parsed)) {
        expect(parsed.method).toBe('GET');
        expect(parsed.path).toBe('/api/v1/bookmarks');
        expect(parsed.status).toBe(200);
        expect(parsed.duration_ms).toBeGreaterThanOrEqual(0);
      }
    }

    consoleSpy.mockRestore();
  });
});

